import{_ as l,a0 as p,w as d,s as o,I as t,x as a,a1 as e,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux 如何設置密碼複雜度？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 如何設置密碼複雜度？ | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 如何設置密碼複雜度？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 如何設置密碼複雜度？ | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20190513 How To Set Password Complexity On Linux","title":"Linux 如何設置密碼複雜度？","tag":"201912","desc":""},"relativePath":"201912/20190513 How To Set Password Complexity On Linux.md","filePath":"[post].md"}'),h={name:"201912/20190513 How To Set Password Complexity On Linux.md"};function c(u,s,g,k,b,m){const i=p("Link");return d(),o("div",null,[s[21]||(s[21]=t("h1",{id:"linux-如何設置密碼複雜度",tabindex:"-1"},[a("Linux 如何設置密碼複雜度？ "),t("a",{class:"header-anchor",href:"#linux-如何設置密碼複雜度","aria-label":"Permalink to “Linux 如何設置密碼複雜度？”"},"​")],-1)),t("p",null,[s[1]||(s[1]=a("對於 Linux 系統管理員來説，用户管理是最重要的事之一。這涉及到很多因素，實現強密碼策略是用户管理的其中一個方面。移步後面的 URL 查看如何 ",-1)),e(i,{href:"https://www.2daygeek.com/5-ways-to-generate-a-random-strong-password-in-linux-terminal/"},{default:n(()=>[...s[0]||(s[0]=[a("在 Linux 上生成一個強密碼",-1)])]),_:1}),s[2]||(s[2]=a("。它會限制系統未授權的用户的訪問。",-1))]),t("p",null,[s[4]||(s[4]=a("所有人都知道 Linux 的默認策略很安全，然而我們還是要做一些微調，這樣才更安全。弱密碼有安全隱患，因此，請特別注意。移步後面的 URL 查看生成的強密碼的",-1)),e(i,{href:"https://www.2daygeek.com/how-to-check-password-complexity-strength-and-score-in-linux/"},{default:n(()=>[...s[3]||(s[3]=[a("密碼長度和分值",-1)])]),_:1}),s[5]||(s[5]=a("。本文將教你在 Linux 中如何實現最安全的策略。",-1))]),s[22]||(s[22]=r(`<p>在大多數 Linux 系統中，我們可以用 PAM（<ruby>可插拔認證模組<rt>pluggable authentication module</rt></ruby>）來加強密碼策略。在下面的路徑可以找到這個文件。</p><ul><li>在紅帽系列的系統中，路徑：<code>/etc/pam.d/system-auth</code>。</li><li>Debian 系列的系統中，路徑：<code>/etc/pam.d/common-password</code>。</li></ul><p>關於默認的密碼過期時間，可以在 <code>/etc/login.defs</code> 文件中查看詳細信息。</p><p>為了更好理解，我摘取了文件的部分內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_MAX_DAYS   99999</span></span>
<span class="line"><span>PASS_MIN_DAYS   0</span></span>
<span class="line"><span>PASS_MIN_LEN    5</span></span>
<span class="line"><span>PASS_WARN_AGE   7</span></span></code></pre></div><p>詳細解釋:</p><ul><li><code>PASS_MAX_DAYS</code>：一個密碼可使用的最大天數。</li><li><code>PASS_MIN_DAYS</code>：兩次密碼修改之間最小的間隔天數。</li><li><code>PASS_MIN_LEN</code>：密碼最小長度。</li><li><code>PASS_WARN_AGE</code>：密碼過期前給出警告的天數。</li></ul><p>我們將會展示在 Linux 中如何實現下面的 11 個密碼策略。</p><ul><li>一個密碼可使用的最大天數</li><li>兩次密碼修改之間最小的間隔天數</li><li>密碼過期前給出警告的天數</li><li>密碼歷史記錄/拒絕重複使用密碼</li><li>密碼最小長度</li><li>最少的大寫字母個數</li><li>最少的小寫字母個數</li><li>最少的數字個數</li><li>最少的其他字符（符號）個數</li><li>賬號鎖定 — 重試</li><li>賬號解鎖時間</li></ul><h3 id="密碼可使用的最大天數是什麼" tabindex="-1">密碼可使用的最大天數是什麼？ <a class="header-anchor" href="#密碼可使用的最大天數是什麼" aria-label="Permalink to “密碼可使用的最大天數是什麼？”">​</a></h3><p>這一參數限制一個密碼可使用的最大天數。它強制用户在過期前修改他/她的密碼。如果他們忘記修改，那麼他們會登錄不了系統。他們需要聯繫管理員才能正常登錄。這個參數可以在 <code>/etc/login.defs</code> 文件中設置。我把這個參數設置為 90 天。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_MAX_DAYS   90</span></span></code></pre></div><h3 id="密碼最小天數是什麼" tabindex="-1">密碼最小天數是什麼？ <a class="header-anchor" href="#密碼最小天數是什麼" aria-label="Permalink to “密碼最小天數是什麼？”">​</a></h3><p>這個參數限制兩次修改之間的最少天數。舉例來説，如果這個參數被設置為 15 天，用户今天修改了密碼，那麼在 15 天之內他都不能修改密碼。這個參數可以在 <code>/etc/login.defs</code> 文件中設置。我設置為 15 天。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_MIN_DAYS   15</span></span></code></pre></div><h3 id="密碼警告天數是什麼" tabindex="-1">密碼警告天數是什麼？ <a class="header-anchor" href="#密碼警告天數是什麼" aria-label="Permalink to “密碼警告天數是什麼？”">​</a></h3><p>這個參數控制密碼警告的前置天數，在密碼即將過期時會給用户警告提示。在警告天數結束前，用户會收到日常警告提示。這可以提醒用户在密碼過期前修改他們的密碼，否則我們就需要聯繫管理員來解鎖密碼。這個參數可以在 <code>/etc/login.defs</code> 文件中設置。我設置為 10 天。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/login.defs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PASS_WARN_AGE   10</span></span></code></pre></div><p><strong>注意:</strong> 上面的所有參數僅對新賬號有效，對已存在的賬號無效。</p><h3 id="密碼歷史或拒絕重複使用密碼是什麼" tabindex="-1">密碼歷史或拒絕重複使用密碼是什麼？ <a class="header-anchor" href="#密碼歷史或拒絕重複使用密碼是什麼" aria-label="Permalink to “密碼歷史或拒絕重複使用密碼是什麼？”">​</a></h3><p>這個參數控制密碼歷史。它記錄曾經使用過的密碼（禁止使用的曾用密碼的個數）。當用户設置新的密碼時，它會檢查密碼歷史，如果他們要設置的密碼是一個曾經使用過的舊密碼，將會發出警告提示。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。我設置密碼歷史為 5。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password  sufficient  pam_unix.so md5 shadow nullok try_first_pass use_authtok remember=5</span></span></code></pre></div><h3 id="密碼最小長度是什麼" tabindex="-1">密碼最小長度是什麼？ <a class="header-anchor" href="#密碼最小長度是什麼" aria-label="Permalink to “密碼最小長度是什麼？”">​</a></h3><p>這個參數表示密碼的最小長度。當用户設置新密碼時，系統會檢查這個參數，如果新設的密碼長度小於這個參數設置的值，會收到警告提示。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。我設置最小密碼長度為 12。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password  requisite   pam_cracklib.so try_first_pass retry=3 minlen=12</span></span></code></pre></div><p><code>try_first_pass retry=3</code>：在密碼設置交互界面，用户有 3 次機會重設密碼。</p><h3 id="設置最少的大寫字母個數" tabindex="-1">設置最少的大寫字母個數？ <a class="header-anchor" href="#設置最少的大寫字母個數" aria-label="Permalink to “設置最少的大寫字母個數？”">​</a></h3><p>這個參數表示密碼中至少需要的大寫字母的個數。這些是密碼強度參數，可以讓密碼更健壯。當用户設置新密碼時，系統會檢查這個參數，如果密碼中沒有大寫字母，會收到警告提示。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。我設置密碼（中的大寫字母）的最小長度為 1 個字母。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password   requisite   pam_cracklib.so try_first_pass retry=3 minlen=12 ucredit=-1</span></span></code></pre></div><h3 id="設置最少的小寫字母個數" tabindex="-1">設置最少的小寫字母個數？ <a class="header-anchor" href="#設置最少的小寫字母個數" aria-label="Permalink to “設置最少的小寫字母個數？”">​</a></h3><p>這個參數表示密碼中至少需要的小寫字母的個數。這些是密碼強度參數，可以讓密碼更健壯。當用户設置新密碼時，系統會檢查這個參數，如果密碼中沒有小寫字母，會收到警告提示。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。我設置為 1 個字母。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password    requisite     pam_cracklib.so try_first_pass retry=3 minlen=12 lcredit=-1</span></span></code></pre></div><h3 id="設置密碼中最少的數字個數" tabindex="-1">設置密碼中最少的數字個數？ <a class="header-anchor" href="#設置密碼中最少的數字個數" aria-label="Permalink to “設置密碼中最少的數字個數？”">​</a></h3><p>這個參數表示密碼中至少需要的數字的個數。這些是密碼強度參數，可以讓密碼更健壯。當用户設置新密碼時，系統會檢查這個參數，如果密碼中沒有數字，會收到警告提示。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。我設置為 1 個數字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password    requisite     pam_cracklib.so try_first_pass retry=3 minlen=12 dcredit=-1</span></span></code></pre></div><h3 id="設置密碼中最少的其他字符-符號-個數" tabindex="-1">設置密碼中最少的其他字符（符號）個數？ <a class="header-anchor" href="#設置密碼中最少的其他字符-符號-個數" aria-label="Permalink to “設置密碼中最少的其他字符（符號）個數？”">​</a></h3><p>這個參數表示密碼中至少需要的特殊符號的個數。這些是密碼強度參數，可以讓密碼更健壯。當用户設置新密碼時，系統會檢查這個參數，如果密碼中沒有特殊符號，會收到警告提示。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。我設置為 1 個字符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>password    requisite     pam_cracklib.so try_first_pass retry=3 minlen=12 ocredit=-1</span></span></code></pre></div><h3 id="設置賬號鎖定" tabindex="-1">設置賬號鎖定？ <a class="header-anchor" href="#設置賬號鎖定" aria-label="Permalink to “設置賬號鎖定？”">​</a></h3><p>這個參數控制用户連續登錄失敗的最大次數。當達到設定的連續失敗登錄次數閾值時，鎖定賬號。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auth        required      pam_tally2.so onerr=fail audit silent deny=5</span></span>
<span class="line"><span>account required pam_tally2.so</span></span></code></pre></div><h3 id="設定賬號解鎖時間" tabindex="-1">設定賬號解鎖時間？ <a class="header-anchor" href="#設定賬號解鎖時間" aria-label="Permalink to “設定賬號解鎖時間？”">​</a></h3><p>這個參數表示用户解鎖時間。如果一個用户賬號在連續認證失敗後被鎖定了，當過了設定的解鎖時間後，才會解鎖。設置被鎖定中的賬號的解鎖時間（900 秒 = 15分鐘）。這個參數可以在 <code>/etc/pam.d/system-auth</code> 文件中設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span>
<span class="line"><span></span></span>
<span class="line"><span>auth        required      pam_tally2.so onerr=fail audit silent deny=5 unlock_time=900</span></span>
<span class="line"><span>account required pam_tally2.so</span></span></code></pre></div><hr>`,45)),t("p",null,[s[7]||(s[7]=a("via: ",-1)),e(i,{href:"https://www.2daygeek.com/how-to-set-password-complexity-policy-on-linux/"},{default:n(()=>[...s[6]||(s[6]=[a("https://www.2daygeek.com/how-to-set-password-complexity-policy-on-linux/",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("作者：",-1)),e(i,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...s[8]||(s[8]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[13]||(s[13]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[9]||(s[9]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 譯者：",-1)),e(i,{href:"https://github.com/lxbwolf"},{default:n(()=>[...s[10]||(s[10]=[a("lxbwolf",-1)])]),_:1}),s[15]||(s[15]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[a("Linux中國",-1)])]),_:1}),s[20]||(s[20]=a(" 榮譽推出",-1))])])}const w=l(h,[["render",c]]);export{x as __pageData,w as default};
